var t=`1379-pira-caldo`;var a=`world-1379`;var n=`PY`;var o=`south-america`;var s=4;var r=60;var l={en:`Pira Caldo`,ua:`Піра кальдо`};var m={en:`Pira Caldo is a dish from Paraguay featuring yellow onion, garlic, red bell pepper, potato. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Піра кальдо, страва кухні країни Парагвай з такими основними складниками: жовта цибуля, часник, червоний солодкий перець, картопля. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var g=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,180,`g`],[`garlic`,5,`clove`],[`red-bell-pepper`,160,`g`],[`olive-oil`,40,`ml`]]},{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 30 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 30 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:30,i:[[`fish-stock`,1e3,`ml`],[`potato`,300,`g`],[`tomato`,280,`g`]]},{en:`Poach the listed ingredients in barely simmering liquid for about 17 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 17 хвилин до готовності й м’якості.`,t:[`poaching`],m:17,i:[[`tilapia`,760,`g`],[`whole-cow-milk`,220,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,25,`g`]]}];var d={slug:t,id:a,country:`PY`,region:o,servings:4,minutes:60,title:l,text:m,steps:g};export{n as country,d as default,a as id,r as minutes,o as region,s as servings,t as slug,g as steps,m as text,l as title};